-- Фло (трекер цикла), фаза 1: профиль и периоды. Данные видит только владелица (tg_id).
CREATE TABLE IF NOT EXISTS cycle_profiles (tg_id INTEGER PRIMARY KEY,avg_cycle_length INTEGER NOT NULL DEFAULT 28,avg_period_length INTEGER NOT NULL DEFAULT 5,share_enabled INTEGER NOT NULL DEFAULT 0,share_level TEXT NOT NULL DEFAULT 'phases',onboarded INTEGER NOT NULL DEFAULT 0,notify_enabled INTEGER NOT NULL DEFAULT 0,notify_period INTEGER NOT NULL DEFAULT 1,notify_ovulation INTEGER NOT NULL DEFAULT 1,notify_fertile INTEGER NOT NULL DEFAULT 1,notify_delay INTEGER NOT NULL DEFAULT 1,notify_period_days INTEGER NOT NULL DEFAULT 2,notify_delay_days INTEGER NOT NULL DEFAULT 3,share_notify INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cycle_periods (id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER NOT NULL,start_date TEXT NOT NULL,end_date TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(tg_id,start_date));
CREATE INDEX IF NOT EXISTS idx_cycle_periods_tg_start ON cycle_periods(tg_id,start_date);
